// Initialize clustering if not already done
if (!global.get('clusters')) {
    // Simple K-means implementation
    global.set('clusters', {
        k: function(numClusters) {
            this._k = numClusters || 3;
            return this;
        },
        iterations: function(iter) {
            this._iterations = iter || 100;
            return this;
        },
        data: function(dataset) {
            this._data = dataset;
            return this;
        },
        clusters: function() {
            if (!this._data || this._data.length === 0) return [];

            var k = this._k || 3;
            var iterations = this._iterations || 100;
            var data = this._data;

            // Initialize centroids randomly
            var centroids = [];
            var min = Math.min(...data.map(d => d[0]));
            var max = Math.max(...data.map(d => d[0]));

            for (var i = 0; i < k; i++) {
                centroids.push([min + (max - min) * Math.random()]);
            }

            // Run K-means iterations
            for (var iter = 0; iter < iterations; iter++) {
                var clusters = [];
                for (var i = 0; i < k; i++) {
                    clusters.push([]);
                }

                // Assign points to nearest centroid
                data.forEach(point => {
                    var minDist = Infinity;
                    var clusterIndex = 0;

                    centroids.forEach((centroid, idx) => {
                        var dist = Math.abs(point[0] - centroid[0]);
                        if (dist < minDist) {
                            minDist = dist;
                            clusterIndex = idx;
                        }
                    });

                    clusters[clusterIndex].push(point);
                });

                // Update centroids
                var newCentroids = [];
                clusters.forEach(cluster => {
                    if (cluster.length > 0) {
                        var sum = cluster.reduce((acc, point) => acc + point[0], 0);
                        newCentroids.push([sum / cluster.length]);
                    } else {
                        newCentroids.push([min + (max - min) * Math.random()]);
                    }
                });

                centroids = newCentroids;
            }

            // Format result similar to school example
            var result = [];
            centroids.forEach((centroid, idx) => {
                result.push({
                    centroid: centroid,
                    cluster: idx,
                    size: clusters[idx] ? clusters[idx].length : 0
                });
            });

            // Sort by centroid value (low to high pollution)
            result.sort((a, b) => a.centroid[0] - b.centroid[0]);

            return result;
        }
    });
}

