            if (clusterCounts.hasOwnProperty(cluster)) {
                clusterCounts[cluster]++;
            } else {
                clusterCounts['unknown']++;
            }
        } else {
            clusterCounts['unknown']++;
        }
    });

    // Get historical cluster performance
    var clusterHistory = flow.get('cluster_performance_history') || [];

    // Add current snapshot
    clusterHistory.push({
        timestamp: timestamp,
        cluster0: clusterCounts['0'],
        cluster1: clusterCounts['1'],
        cluster2: clusterCounts['2'],
        unknown: clusterCounts['unknown']
    });

    // Keep only last 24 hours
    var dayAgo = Date.now() - (24 * 60 * 60 * 1000);
    clusterHistory = clusterHistory.filter(h => h.timestamp > dayAgo);
    flow.set('cluster_performance_history', clusterHistory);

    // Prepare chart data
    var cluster0Data = [];
    var cluster1Data = [];
    var cluster2Data = [];

    clusterHistory.forEach(point => {
        cluster0Data.push({ x: point.timestamp, y: point.cluster0 });
        cluster1Data.push({ x: point.timestamp, y: point.cluster1 });
        cluster2Data.push({ x: point.timestamp, y: point.cluster2 });
    });

    msg.payload = [{
        series: ['Low Pollution (C0)', 'Moderate Pollution (C1)', 'High Pollution (C2)'],
        data: [cluster0Data, cluster1Data, cluster2Data],
        labels: ['Cluster 0', 'Cluster 1', 'Cluster 2']
    }];

    return msg;
}

